// Shared geometry for preview, spacing and exported outlines.
export function makePrimitives(cells,columns,options){
 const shape=options.shape,weight=options.weight/100,gap=(options.separation||0)/100,width=Math.max(.06,weight*(1-gap)),round=(options.roundness??(shape==='squares'?0:55))/100,items=[],set=new Set(cells),connected=['rounded','ribbon','organic'].includes(shape);
 const center=i=>{let x=i%columns+.5,y=Math.floor(i/columns)+.5;if(shape==='organic'){const hash=n=>{const v=Math.sin(n*127.1+37.2)*43758.5453;return v-Math.floor(v)-.5};x+=hash(i+1)*.16;y+=hash(i+53)*.16}return [x,y]};
 const circles=new Set();const circle=(x,y,r)=>{const key=[x,y,r].map(v=>v.toFixed(6)).join(',');if(circles.has(key))return;circles.add(key);items.push({type:'circle',x,y,r})};
 function segment(a,b){if(Math.hypot(b[0]-a[0],b[1]-a[1])<1e-8)return;if(shape==='ribbon'){const dx=b[0]-a[0],dy=b[1]-a[1],len=Math.hypot(dx,dy);if(!len)return;const nx=-dy/len*weight/2,ny=dx/len*weight/2,overlap=.015;a=[a[0]-dx/len*overlap,a[1]-dy/len*overlap];b=[b[0]+dx/len*overlap,b[1]+dy/len*overlap];items.push({type:'polygon',points:[[a[0]+nx,a[1]+ny],[b[0]+nx,b[1]+ny],[b[0]-nx,b[1]-ny],[a[0]-nx,a[1]-ny]]})}else{items.push({type:'line',x:a[0],y:a[1],x2:b[0],y2:b[1],width:weight});circle(...a,weight/2);circle(...b,weight/2)}}
 if(connected){const graph=new Map(cells.map(i=>[i,[]]));for(const i of cells){const x=i%columns,y=Math.floor(i/columns);for(const [dx,dy]of [[1,0],[0,1],[1,1],[-1,1]]){const xx=x+dx,yy=y+dy,j=yy*columns+xx;if(xx<0||xx>=columns||!set.has(j))continue;// Do not shortcut an existing orthogonal corner.
 if(dx&&dy&&(set.has(y*columns+xx)||set.has(yy*columns+x)))continue;graph.get(i).push(j);graph.get(j).push(i)}}
 const visited=new Set(),edge=(a,b)=>[Math.min(a,b),Math.max(a,b)].join(':');
 function stroke(ids){let points=ids.map(center);const closed=ids[0]===ids.at(-1)&&ids.length>2;if(closed){const loop=points.slice(0,-1),a=loop[0],b=loop.at(-1),mid=[(a[0]+b[0])/2,(a[1]+b[1])/2];points=[mid,...loop,mid]}if(points.length===1){circle(...points[0],weight/2);return}let previous=points[0];for(let k=1;k<points.length-1;k++){const a=points[k-1],b=points[k],c=points[k+1],t=.42*round,enter=[b[0]+(a[0]-b[0])*t,b[1]+(a[1]-b[1])*t],leave=[b[0]+(c[0]-b[0])*t,b[1]+(c[1]-b[1])*t];if(Math.abs((b[0]-a[0])*(c[1]-b[1])-(b[1]-a[1])*(c[0]-b[0]))<1e-8){segment(previous,b);previous=b;continue;}segment(previous,enter);let last=enter;for(let n=1;n<=6;n++){const u=n/6,v=1-u,next=[v*v*enter[0]+2*v*u*b[0]+u*u*leave[0],v*v*enter[1]+2*v*u*b[1]+u*u*leave[1]];segment(last,next);last=next}previous=leave}segment(previous,points.at(-1));if(shape==='ribbon'){for(const [x,y]of [points[0],points.at(-1)])items.push({type:'rect',x:x-weight/2,y:y-weight/2,width:weight})}}
 function walk(start,next){const ids=[start];let a=start,b=next;while(true){visited.add(edge(a,b));ids.push(b);const neighbors=graph.get(b);if(neighbors.length!==2||b===start)break;const c=neighbors.find(i=>i!==a);if(visited.has(edge(b,c)))break;a=b;b=c}stroke(ids)}
 for(const i of cells){const neighbors=graph.get(i);if(!neighbors.length)stroke([i]);if(neighbors.length!==2)for(const j of neighbors)if(!visited.has(edge(i,j)))walk(i,j)}for(const i of cells)for(const j of graph.get(i))if(!visited.has(edge(i,j)))walk(i,j);
 }else for(const i of cells){const [x,y]=center(i),r=width/2;if(shape==='diamond'||shape==='triangle')items.push({type:'polygon',points:shape==='diamond'?[[x,y-r],[x+r,y],[x,y+r],[x-r,y]]:[[x,y-r],[x+r,y+r],[x-r,y+r]]});else if(shape==='ring')items.push({type:'ring',x,y,r,inner:r*.55});else if(shape==='capsule'){const points=[];for(let n=0;n<=16;n++){const a=n*Math.PI/16;points.push([x+Math.cos(a)*width*.32,y+width*.30+Math.sin(a)*width*.32])}for(let n=0;n<=16;n++){const a=Math.PI+n*Math.PI/16;points.push([x+Math.cos(a)*width*.32,y-width*.30+Math.sin(a)*width*.32])}items.push({type:'polygon',points});}else if(shape==='bevel'){const d=r*.42;items.push({type:'polygon',points:[[x-r+d,y-r],[x+r-d,y-r],[x+r,y-r+d],[x+r,y+r-d],[x+r-d,y+r],[x-r+d,y+r],[x-r,y+r-d],[x-r,y-r+d]]})}else if(shape==='squares'&&round>0){const radius=r*round,points=[];for(let q=0;q<4;q++){const a=q*Math.PI/2,cx=x+(q===0||q===3?1:-1)*(r-radius),cy=y+(q<2?1:-1)*(r-radius);for(let n=0;n<=8;n++){const angle=a+n*Math.PI/16;points.push([cx+Math.cos(angle)*radius,cy+Math.sin(angle)*radius])}}items.push({type:'polygon',points});}else if(shape==='squares')items.push({type:'rect',x:x-r,y:y-r,width});else circle(x,y,r)}
 return items;
}
export function outlineBounds(items,y){let min=Infinity,max=-Infinity;for(const p of items){let a=Infinity,b=-Infinity;if(p.type==='circle'||p.type==='ring'){const d=y-p.y;if(Math.abs(d)<=p.r){const dx=Math.sqrt(Math.max(0,p.r*p.r-d*d));a=p.x-dx;b=p.x+dx}}else if(p.type==='rect'){if(y>=p.y&&y<=p.y+p.width){a=p.x;b=p.x+p.width}}else if(p.type==='polygon'){const xs=[];for(let i=0;i<p.points.length;i++){const u=p.points[i],v=p.points[(i+1)%p.points.length];if(u[1]===v[1]){if(y===u[1])xs.push(u[0],v[0]);continue}if(y>=Math.min(u[1],v[1])&&y<=Math.max(u[1],v[1]))xs.push(u[0]+(y-u[1])*(v[0]-u[0])/(v[1]-u[1]))}if(xs.length){a=Math.min(...xs);b=Math.max(...xs)}}else if(p.type==='line'){const dx=p.x2-p.x,dy=p.y2-p.y,len=Math.hypot(dx,dy);if(!len)continue;const nx=-dy/len*p.width/2,ny=dx/len*p.width/2;[a,b]=outlineBounds([{type:'polygon',points:[[p.x+nx,p.y+ny],[p.x2+nx,p.y2+ny],[p.x2-nx,p.y2-ny],[p.x-nx,p.y-ny]]}],y)}min=Math.min(min,a);max=Math.max(max,b)}return [min,max]}
